package vn.gastroai.be.infrastructure.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.*; public class AdminSessionFilter extends OncePerRequestFilter { protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{HttpSession s=req.getSession(false);if(SecurityContextHolder.getContext().getAuthentication()==null&&s!=null&&s.getAttribute("ADMIN_ID")!=null){var a=new UsernamePasswordAuthenticationToken(s.getAttribute("ADMIN_ID").toString(),null,List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));SecurityContextHolder.getContext().setAuthentication(a);}chain.doFilter(req,res);} }
